import{_ as t,o,c as r,ag as s}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 4 Homework","description":"","frontmatter":{"source":"weeks/04-undo-compare-explain/homework.md"},"headers":[],"relativePath":"weeks/04-undo-compare-explain/homework.md","filePath":"weeks/04-undo-compare-explain/homework.md"}'),a={name:"weeks/04-undo-compare-explain/homework.md"};function n(i,e,h,d,l,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="week-4-homework" tabindex="-1">Week 4 Homework <a class="header-anchor" href="#week-4-homework" aria-label="Permalink to &quot;Week 4 Homework&quot;">​</a></h1><blockquote><p><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). <strong>Core:</strong> about 5 hours plus the journal, required. <strong>Stretch:</strong> optional. Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">rubric</a>). &quot;On Canvas&quot; means the course&#39;s learning management system, not Gemini&#39;s Canvas tool.</p></blockquote><p>Use the <a href="./../../resources/safe-loop.html">Safe Loop</a> for every change: Describe → Plan → Step → Test → Read → Commit.</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><ul><li>☐ My game has <strong>one more feature</strong>, with its &quot;Done when&quot; written first, built in <strong>at least three commits</strong>, each with a teach-back in <code>PROMPTS.md</code> and an <code>Assisted-by:</code> line (task 1).</li><li>☐ My game&#39;s <strong>History</strong> shows the Studio A break and restore, and my <strong>restore drill</strong> (task 2).</li><li>☐ <code>prompt-makeover.md</code> in my home-page repository has my four rewrites (🔴 AI off) and the result of testing one (task 3).</li><li>☐ My game uses the function in <code>game/logic.js</code>, and <code>npm test</code> passes, including my own test (task 4).</li><li>☐ <code>PROMPTS.md</code> has this week&#39;s entries (task 5).</li><li>☐ On Canvas: my <strong>weekly reflection</strong> (🔴 AI off) (task 6).</li></ul><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. One more feature in three save points</td><td>Project time</td><td>2 h</td></tr><tr><td>2. Restore drill</td><td>Homework</td><td>30 min</td></tr><tr><td>3. Prompt makeover</td><td>Homework</td><td>1 h</td></tr><tr><td>4. Make your game use the tested function</td><td>Homework</td><td>1 h 15 min</td></tr><tr><td>5. <code>PROMPTS.md</code></td><td>Journal</td><td>15 min</td></tr><tr><td>6. Weekly reflection</td><td>Journal</td><td>20 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 5½ h</strong></td></tr></tbody></table><p>Do task 4 <strong>after</strong> task 1: once your game imports <code>logic.js</code>, a chat preview can&#39;t run it any more.</p><p>Before next week&#39;s Studio A, also do the &quot;Before class&quot; list on the <a href="./../05-spec-first/">week 5 page</a> (up to 30 minutes).</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-one-more-feature-in-three-save-points-2-h" tabindex="-1">1. One more feature in three save points (2 h) <a class="header-anchor" href="#1-one-more-feature-in-three-save-points-2-h" aria-label="Permalink to &quot;1. One more feature in three save points (2 h)&quot;">​</a></h3><p>🟢 AI on · 🔴 AI off for your &quot;Done when&quot; and your teach-backs.</p><p>Add <strong>one</strong> feature your game doesn&#39;t have yet. Ideas:</p><ul><li><strong>A high score that survives a reload</strong>, in <strong><a href="./../../resources/glossary.html#localstorage">localStorage</a></strong>: a small storage space the browser keeps for your site on this device only.</li><li><strong>Sound effects</strong>, generated in code (the browser&#39;s Web Audio API, no sound files), with a mute button.</li><li><strong>Touch controls</strong> so the game works on your phone.</li><li><strong>A second level</strong> that starts when level 1 is won.</li><li><strong>Pause and resume</strong>, or a <strong>difficulty</strong> setting.</li></ul><ol><li><strong><a href="./../../resources/safe-loop.html#check-first">Check first</a>.</strong> Before you ask the AI anything, write the feature&#39;s &quot;Done when&quot; in <code>PROMPTS.md</code> yourself, as things you&#39;ll try by hand (you may have started in Part A3).</li><li><strong>Plan.</strong> Ask for three small steps, each with a &quot;Done when&quot;, pasting your complete file. Edit the plan until it meets <em>your</em> &quot;Done when&quot;.</li><li><strong>Build each step</strong> with the Safe Loop: step prompt, test, read the diff.</li><li><strong><a href="./../../resources/safe-loop.html#teach-back">Teach back</a> before each commit</strong> (🔴 AI off): 2–3 sentences in <code>PROMPTS.md</code> on what changed, why it works, and what you&#39;d check first if it broke. Can&#39;t write it? Ask the AI to explain the diff, read it again, then write it yourself.</li><li><strong>Commit</strong> each working step with an <code>Assisted-by:</code> line.</li></ol><p>✅ <strong>Checkpoint:</strong> the feature meets the &quot;Done when&quot; you wrote first, in at least three commits, each with a teach-back in <code>PROMPTS.md</code>.</p><h3 id="2-restore-drill-30-min" tabindex="-1">2. Restore drill (30 min) <a class="header-anchor" href="#2-restore-drill-30-min" aria-label="Permalink to &quot;2. Restore drill (30 min)&quot;">​</a></h3><p>🔴 AI off.</p><p>Going back to a working version is one of the <a href="./../../resources/without-ai-skills.html">six skills you must show without AI</a>, and your first oral walkthrough (week 8) asks for it. Practice once more, <strong>without the lab open</strong>: break your game or home page by hand (delete a <code>&gt;</code> or a <code>}</code>) and commit it as <code>Experiment: restore drill</code>; restore the last working version from <strong>History</strong> as <code>Restore working version from [hash]</code>; check the live page; close and reopen github.dev. In <code>PROMPTS.md</code>, note the hash and any step you had to look up.</p><h3 id="3-prompt-makeover-1-h" tabindex="-1">3. Prompt makeover (1 h) <a class="header-anchor" href="#3-prompt-makeover-1-h" aria-label="Permalink to &quot;3. Prompt makeover (1 h)&quot;">​</a></h3><p>🔴 AI off for the rewrites · 🟢 AI on for testing one.</p><ol><li>Create <code>prompt-makeover.md</code> in your home-page repository, with your rewrite of prompt <strong>A</strong> from <a href="./lab.html#part-b3--prompt-makeover-workshop-10-min">Part B3</a>, improved with your neighbor&#39;s suggestion.</li><li>Rewrite <strong>B, C and D</strong> in four parts, <strong>yourself, without AI</strong>, and check each against Part B3&#39;s four questions.</li><li><strong>Test one</strong> (🟢 AI on): send it to an assistant, and say in two sentences under it whether the result met your &quot;Done when&quot; and what you&#39;d change next time. Commit.</li></ol><h3 id="4-make-your-game-use-the-tested-function-1-h-15-min" tabindex="-1">4. Make your game use the tested function (1 h 15 min) <a class="header-anchor" href="#4-make-your-game-use-the-tested-function-1-h-15-min" aria-label="Permalink to &quot;4. Make your game use the tested function (1 h 15 min)&quot;">​</a></h3><p>🟡 AI limited: the AI may explain an error; you make the changes.</p><p>In Studio B you tested a copy of your function in <code>game/logic.js</code>. Now make the game use that file, so the code you tested is the code that runs.</p><ol><li><p><strong>Fix what your own test found</strong> (lab <a href="./lab.html#part-b2--your-first-automated-test-35-min">Part B2</a>, step 7), if it failed: decide the right answer, change <code>logic.js</code>, and run <code>npm test</code> until it&#39;s green. If you decide the test was wrong instead, say why in <code>PROMPTS.md</code>.</p></li><li><p>In a Codespace (or on your own computer), open <code>game/index.html</code>. Change the game&#39;s <code>&lt;script&gt;</code> tag to <code>&lt;script type=&quot;module&quot;&gt;</code>, and add this as the first line inside it, with your function&#39;s name:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { averageTime } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;./logic.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p><strong>Delete the old copy</strong> of the function from <code>index.html</code>, so there&#39;s only one.</p></li><li><p><strong>Test the game by hand.</strong> In the terminal, run <code>python3 -m http.server 8000</code>, open the forwarded port, and go to <code>/game/</code> (add <code>game/</code> to the end of the address). Play it through; check the browser&#39;s Console for red errors. Stop the server with <code>Ctrl+C</code>.</p></li><li><p>Run <code>npm test</code> once more, then commit and push: <code>Use tested [function] from logic.js</code>.</p></li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Three things change when the game&#39;s script becomes a module. (1) <code>onclick=&quot;startGame()&quot;</code> in your HTML stops working, because a module&#39;s functions aren&#39;t global: switch to <code>addEventListener</code>, or ask the AI to explain how. (2) A module only works when the page is served (a Codespace preview or GitHub Pages), not opened from your computer&#39;s files, and a chat preview can&#39;t see <code>logic.js</code>. (3) If the game breaks and two fixes fail, that&#39;s the <strong>two-strikes rule</strong>: restore the last working version from History, and ask for help in office hours.</p></div><p>✅ <strong>Checkpoint:</strong> your live game works and uses <code>game/logic.js</code>, and <code>npm test</code> passes.</p><h3 id="5-promptsmd-15-min" tabindex="-1">5. <code>PROMPTS.md</code> (15 min) <a class="header-anchor" href="#5-promptsmd-15-min" aria-label="Permalink to &quot;5. `PROMPTS.md` (15 min)&quot;">​</a></h3><p>🟢 AI on for formatting · 🔴 AI off for &quot;What I wrote or decided myself&quot; and the teach-backs.</p><p>Add a <strong>Week 4</strong> heading, with the prompts written in four-part form (<strong>Goal · Context · Constraints · Done when</strong>):</p><ul><li>the Studio A restore and your restore drill, with the hashes;</li><li>your model comparison: your &quot;Done when&quot;, the table from Part A2, and the winner;</li><li>anything from the peer swap you looked up afterwards;</li><li>your first test: the function, and your own test&#39;s prediction and result;</li><li>your feature: its &quot;Done when&quot;, the plan, and a teach-back for each commit.</li></ul><p>Update <strong>What I wrote or decided myself</strong> (your tests, your restore, the rewrites) and <strong>What I&#39;d prompt differently next time</strong>. Commit with a clear message.</p><h3 id="6-weekly-reflection-20-min" tabindex="-1">6. Weekly reflection (20 min) <a class="header-anchor" href="#6-weekly-reflection-20-min" aria-label="Permalink to &quot;6. Weekly reflection (20 min)&quot;">​</a></h3><p>🔴 AI off.</p><p>Answer the four questions in the <a href="./../../templates/REFLECTION.html">reflection template</a> in 150–300 words, <strong>without AI</strong>. Good moments to write about: the second you broke your game on purpose, a difference between the two models&#39; answers, explaining a classmate&#39;s function, or the first time a test went red. Submit it on <strong>Canvas</strong>, not in your repository (<a href="./../../assessment/#privacy-of-your-work">Privacy of your work</a>).</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><p>Each is a small Safe Loop: commit after each working step, and log your prompts in <code>PROMPTS.md</code>.</p><ul><li><strong>A test written first, for your feature.</strong> If your feature has a pure piece (such as <code>isNewBest(score, best)</code>), write its test in <code>tests/logic.test.js</code>, see it fail, then ask for the code. That&#39;s <strong>check first</strong> as it works from week 6; the <a href="./../../resources/prompt-patterns.html#16-check-first-test-prompt">check-first test prompt</a> asks an AI for a test without showing it the code.</li><li><strong>A second tested function</strong>, with an edge-case test, or <strong>a second feature</strong> from task 1.</li></ul><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> you can restore an earlier version of a file from its History, and <code>npm test</code> runs at least one passing test in your home-page repository. Week 5 starts a new project in a new repository with the same commit habits, and from week 6 its checks are automated tests like this one. If either isn&#39;t working, ask your instructor for help before Studio A.</p></div>',41)])])}const p=t(a,[["render",n]]);export{u as __pageData,p as default};
